files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #EAEAEA;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247CFF;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #000000;
  --vt-accent-on-deep: #247CFF;
  --vt-line: #EAEAEA;
  background-color: var(--vt-surface);
  color: var(--vt-ink);
  font-family: 'Open Sans', sans-serif;
  line-height: 1.6;
}

.root h1,
.root h2,
.root h3,
.root h4,
.root h5,
.root h6 {
  color: var(--vt-ink);
  font-weight: 600;
}

.root p {
  color: var(--vt-ink-soft);
}

.root a {
  text-decoration: none;
  transition: color 0.3s;
}

.root a:hover {
  color: var(--vt-accent);
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background-color: var(--vt-surface);
  box-shadow: 0 0.125rem 0.25rem color-mix(in srgb, var(--vt-ink) 10%, transparent);
}

.navIn {
  max-width: 1200px;
  margin: 0 auto;
  padding: 1rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  text-decoration: none;
}

.brand {
  /* Brand component styles are handled internally */
}

.navLinks {
  display: flex;
  gap: 2rem;
}

.navLinks a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  font-weight: 600;
  font-size: 1rem;
  padding: 0.5rem 0;
}

.navLinks a:hover,
.navLinks a:focus-visible {
  color: var(--vt-ink);
}

.hero {
  margin-top: 94px;
  position: relative;
}

.heroTrack {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  height: 580px;
  scrollbar-width: none;
}

.heroTrack::-webkit-scrollbar {
  display: none;
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  position: relative;
  margin: 0;
}

.heroSlide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  position: absolute;
  bottom: 0;
  right: 0;
  z-index: 2;
  width: 50%;
  background: var(--vt-surface);
  padding: 2rem 2.5rem;
  box-shadow: 0 0.5rem 1rem color-mix(in srgb, var(--vt-ink) 15%, transparent);
}

.heroText h1 {
  margin: 0 0 0.5rem;
  font-size: 3rem;
  line-height: 1.2;
  color: var(--vt-ink);
}

.kicker {
  color: var(--vt-accent);
  font-weight: 600;
  margin: 0 0 0.5rem;
}

.heroText p {
  margin: 0 0 1rem;
  color: var(--vt-ink-soft);
}

.heroLinks {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  position: relative;
  overflow: hidden;
  text-align: center;
  background-color: transparent;
  transition: color 0.3s;
}

.customLink::before {
  content: attr(data-hover);
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--vt-line);
  color: var(--vt-accent-ink);
  transition: top 300ms cubic-bezier(0.19, 1, 0.56, 1);
  text-align: center;
  line-height: 40px;
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
  margin: 0;
}

.sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.aboutGrid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

.aboutText h2 {
  margin: 0 0 1.5rem;
  color: var(--vt-ink);
  font-size: 2.25rem;
}

.aboutText p {
  color: var(--vt-ink-soft);
  font-size: 1rem;
  line-height: 1.8;
  margin-bottom: 1rem;
}

.gallerySection {
  background-color: var(--vt-surface-2);
}

.galleryRow {
  display: flex;
  gap: 0;
}

.galleryItem {
  flex: 1;
  margin: 0;
}

.galleryImage {
  width: 100%;
  height: auto;
  display: block;
}

.sectionTitle {
  text-align: center;
  margin-bottom: 4rem;
  color: var(--vt-ink);
  font-size: 2.25rem;
}

.timeline {
  position: relative;
  padding: 2rem 0;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  width: 1px;
  height: 100%;
  background-color: var(--vt-line);
  transform: translateX(-50%);
  z-index: 1;
}

.timelineNode {
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 4rem;
  z-index: 2;
}

.timelineNode:last-child {
  margin-bottom: 0;
}

.even {
  flex-direction: row;
}

.odd {
  flex-direction: row-reverse;
}

.timelineContent {
  width: 45%;
  background-color: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem color-mix(in srgb, var(--vt-ink) 10%, transparent);
  border-radius: 0.25rem;
  padding: 0;
  position: relative;
}

.timelineContent h3 {
  background-color: var(--vt-ink);
  color: var(--vt-on-deep);
  padding: 0.75rem 1.5rem;
  margin: 0;
  font-size: 1.25rem;
  border-radius: 0.25rem 0.25rem 0 0;
  position: relative;
}

.timelineContent p {
  padding: 1rem 1.5rem;
  margin: 0;
  color: var(--vt-ink-soft);
}

.even .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translateY(-50%);
  border-right: 10px solid var(--vt-ink);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.odd .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  border-left: 10px solid var(--vt-ink);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineIconWrap {
  width: 80px;
  height: 80px;
  background-color: var(--vt-surface);
  border-radius: 50%;
  box-shadow: 0 1rem 3rem color-mix(in srgb, var(--vt-ink) 17.5%, transparent);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 3;
  flex-shrink: 0;
}

.timelineIcon {
  width: 40px;
  height: 40px;
  background-color: var(--vt-accent);
  border-radius: 50%;
  display: block;
}

.timelineDate {
  width: 45%;
  padding-top: 1rem;
}

.even .timelineDate {
  text-align: left;
}

.odd .timelineDate {
  text-align: right;
}

.timelineDate time {
  color: var(--vt-ink-soft);
  font-size: 0.9rem;
  font-weight: 600;
}

.siteFooter {
  background-color: var(--vt-surface-2);
  padding: 4rem 0 2rem;
}

.footerGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  margin-bottom: 2rem;
}

.footerCol h5 {
  color: var(--vt-ink);
  margin-bottom: 1rem;
  font-size: 1.25rem;
}

.footerCol p,
.footerCol a {
  color: var(--vt-ink-soft);
  margin: 0 0 0.5rem;
  line-height: 1.6;
}

.footerCol a:hover {
  color: var(--vt-accent);
}

.copyright {
  text-align: center;
  border-top: 1px solid var(--vt-line);
  padding-top: 1.5rem;
}

.copyright p {
  margin: 0;
  color: var(--vt-ink-soft);
  font-size: 0.9rem;
}

@media screen and (min-width: 1600px) {
  .heroTrack {
    height: 740px;
  }
}

@media screen and (max-width: 991px) {
  .navIn {
    padding: 0.75rem 1.5rem;
  }
  .hero {
    margin-top: 74px;
  }
  .heroTrack {
    height: auto;
  }
  .heroText {
    position: relative;
    width: auto;
    bottom: 0;
    left: 0;
    margin-bottom: -100px;
    padding: 2rem;
  }
  .sectionPadding {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }
  .heroText h1 {
    font-size: 2.5rem;
  }
  .footerGrid {
    grid-template-columns: 1fr 1fr;
  }
}

@media screen and (max-width: 767px) {
  .heroText {
    padding: 1.5rem;
  }
  .timeline::before {
    left: 33px;
  }
  .timelineNode {
    flex-direction: column;
    padding-left: 80px;
  }
  .even,
  .odd {
    flex-direction: column;
  }
  .timelineContent {
    width: 100%;
  }
  .timelineNode .timelineDate {
    width: 100%;
    text-align: left;
    padding-top: 0.5rem;
  }
  .timelineIconWrap {
    position: absolute;
    left: 0;
    top: 0;
    width: 70px;
    height: 70px;
  }
  .timelineContent h3::after {
    display: none;
  }
  .footerGrid {
    grid-template-columns: 1fr;
  }
  .navLinks {
    display: none;
  }
}

@media screen and (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }
  .heroLinks {
    gap: 0.5rem;
  }
  .customLink {
    font-size: 12px;
    line-height: 30px;
    padding: 0 20px;
  }
  .contactPhone {
    font-size: 12px;
  }
  .sectionTitle {
    font-size: 1.8rem;
  }
}

@media screen and (max-width: 360px) {
  .timeline::before {
    left: 42px;
  }
  .timelineIconWrap {
    width: 60px;
    height: 60px;
  }
  .timelineIcon {
    width: 30px;
    height: 30px;
  }
}
